-- Phase 7 native PartySessionEndpointRegistry authority (ADR-0123,
-- ADR-0127; PRD-PARTY-003..004).
--
-- The full Party/Queue controller families remain preserved-negative. These
-- two tables retain only the migrated session facts needed by the separately
-- compiled `/api/v1/endpoints*` registry contract. Session public IDs are
-- migration data and are never regenerated by this adapter.

CREATE TABLE native_endpoint_sessions (
    session_public_api_id uuid PRIMARY KEY,
    owner_user_id uuid NOT NULL REFERENCES native_users (id) ON DELETE RESTRICT,
    active_endpoint_id uuid NULL REFERENCES native_playback_endpoints (id) ON DELETE SET NULL,
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL,
    updated_at timestamptz NOT NULL,
    CONSTRAINT native_endpoint_sessions_time CHECK (created_at <= updated_at)
);

CREATE UNIQUE INDEX native_endpoint_sessions_active_endpoint_idx
    ON native_endpoint_sessions (active_endpoint_id)
    WHERE active_endpoint_id IS NOT NULL;

CREATE TABLE native_endpoint_session_members (
    session_public_api_id uuid NOT NULL
        REFERENCES native_endpoint_sessions (session_public_api_id) ON DELETE CASCADE,
    user_id uuid NOT NULL REFERENCES native_users (id) ON DELETE CASCADE,
    role text NOT NULL,
    joined_at timestamptz NOT NULL,
    PRIMARY KEY (session_public_api_id, user_id),
    CONSTRAINT native_endpoint_session_members_role CHECK (
        role IN ('owner', 'dj', 'listener')
    )
);

CREATE INDEX native_endpoint_session_members_user_idx
    ON native_endpoint_session_members (user_id, session_public_api_id);

CREATE FUNCTION native_endpoint_session_owner_is_member() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM native_endpoint_session_members member
        WHERE member.session_public_api_id = NEW.session_public_api_id
          AND member.user_id = NEW.owner_user_id
          AND member.role = 'owner'
    ) THEN
        RAISE EXCEPTION 'endpoint session owner must have the owner membership'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;

CREATE CONSTRAINT TRIGGER native_endpoint_session_owner_member_deferred
AFTER INSERT OR UPDATE OF session_public_api_id, owner_user_id
ON native_endpoint_sessions
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION native_endpoint_session_owner_is_member();

CREATE FUNCTION native_endpoint_membership_preserves_owner() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    affected_session uuid;
BEGIN
    affected_session := CASE
        WHEN TG_OP = 'DELETE' THEN OLD.session_public_api_id
        ELSE NEW.session_public_api_id
    END;
    IF EXISTS (
        SELECT 1 FROM native_endpoint_sessions session
        WHERE session.session_public_api_id = affected_session
          AND NOT EXISTS (
              SELECT 1 FROM native_endpoint_session_members member
              WHERE member.session_public_api_id = session.session_public_api_id
                AND member.user_id = session.owner_user_id
                AND member.role = 'owner'
          )
    ) THEN
        RAISE EXCEPTION 'endpoint session owner must retain the owner membership'
            USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'UPDATE'
       AND OLD.session_public_api_id IS DISTINCT FROM NEW.session_public_api_id
       AND EXISTS (
           SELECT 1 FROM native_endpoint_sessions session
           WHERE session.session_public_api_id = OLD.session_public_api_id
             AND NOT EXISTS (
                 SELECT 1 FROM native_endpoint_session_members member
                 WHERE member.session_public_api_id = session.session_public_api_id
                   AND member.user_id = session.owner_user_id
                   AND member.role = 'owner'
             )
       ) THEN
        RAISE EXCEPTION 'endpoint session owner must retain the owner membership'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;

CREATE CONSTRAINT TRIGGER native_endpoint_membership_owner_deferred
AFTER UPDATE OF session_public_api_id, user_id, role OR DELETE
ON native_endpoint_session_members
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION native_endpoint_membership_preserves_owner();
